import { createRouter } from "@tanstack/react-router";
import {
  type CountryLanguage,
  CountryLanguageValues,
  defaultLocale,
} from "next-vibe/core/i18n/core/config";
import { createClientLogger } from "next-vibe/logger/client";
import { reportRenderError } from "next-vibe/logger/report-render-error";
import { getCurrentPathname } from "next-vibe/ui/lib/location";

// routeTree.gen.ts is auto-generated by the tanstackStart Vite plugin.
// Run `vibe dev --tanstack` once to generate it.
import { routeTree } from "./routeTree.gen";

export function getRouter(): ReturnType<typeof createRouter> {
  return createRouter({
    routeTree,
    defaultPreload: false,
    scrollRestoration: true,
    defaultNotFoundComponent: () => null,
    // During initial hydration, code-split route components suspend briefly
    // while their lazy chunk loads. Without a pending component, the Suspense
    // boundary shows nothing (blank flash). Setting a 0ms pending delay and
    // no pending component keeps existing SSR content visible until the chunk
    // is ready - React 18 will paint the SSR content then swap in-place.
    defaultPendingMs: 0,
    defaultPendingMinMs: 0,
    // Route errors are caught by TanStack's CatchBoundary and rendered as an
    // error page — server-side that produced completely SILENT 500s (nothing
    // in the dev log). Surface them; on the client React logs them anyway.
    defaultOnCatch: (caught, errorInfo): void => {
      const error = caught instanceof Error ? caught : new Error(String(caught));
      if (typeof window === "undefined") {
        process.stderr.write(
          `[SSR route error] ${error.stack || String(error)}\n`,
        );
        return;
      }
      // Route CatchBoundaries sit INSIDE the root ErrorBoundary, so a route
      // crash never reaches it - report here or it only hits the console.
      const localeSegment = getCurrentPathname().split("/")[1] ?? "";
      const locale: CountryLanguage =
        Object.values(CountryLanguageValues).find(
          (value) => value === localeSegment,
        ) ?? defaultLocale;
      reportRenderError({
        logger: createClientLogger(false, locale),
        boundary: "TanStackRouteCatch",
        error,
        componentStack: errorInfo?.componentStack ?? null,
      });
    },
  });
}

declare module "@tanstack/react-router" {
  interface Register {
    router: ReturnType<typeof getRouter>;
  }
}
// test
